# ============================================================
# HELPERS
# ============================================================

def sync():
    torch.cuda.synchronize()


def rand_half(shape, scale=1.0):
    return (
        torch.randn(
            *shape,
            device=DEVICE,
            dtype=DTYPE,
        ) * scale
    ).contiguous()


def bench_ms(
    fn,
    warmup=30,
    iters=100,
):

    for _ in range(warmup):
        fn()

    sync()

    start = torch.cuda.Event(
        enable_timing=True
    )

    end = torch.cuda.Event(
        enable_timing=True
    )

    start.record()

    for _ in range(iters):
        fn()

    end.record()

    sync()

    return start.elapsed_time(end) / iters


def choose_iters(numel):

    if numel <= 8192:
        return 300

    if numel <= 131072:
        return 150

    if numel <= 1048576:
        return 80

    return 40


def check_close(
    name,
    got,
    ref,
    kernel,
    shape,
    atol=5e-2,
    rtol=5e-2,
):

    got = got.float()
    ref = ref.float()

    if got.shape != ref.shape:

        raise AssertionError(
            f"{kernel} {shape}: "
            f"{name} shape mismatch: "
            f"{got.shape} vs {ref.shape}"
        )

    diff = (
        got - ref
    ).abs()

    max_err = diff.max().item()

    if not torch.allclose(
        got,
        ref,
        atol=atol,
        rtol=rtol,
    ):

        idx = diff.argmax().item()

        raise AssertionError(
            f"{kernel} {shape}: "
            f"{name} mismatch\n"
            f"max_err={max_err}\n"
            f"index={idx}\n"
            f"got={got.flatten()[idx].item()}\n"
            f"ref={ref.flatten()[idx].item()}"
        )

    return max_err


def run_test(
    name,
    shape,
    fn,
):

    try:

        result = fn()

        print(
            f"  PASS {shape} | {result}"
        )

    except Exception as e:

        print(
            f"  FAIL {shape} | {e}"
        )

        FAILURES.append(
            (
                name,
                shape,
                str(e),
            )
        )


