def print_bench(
    pytorch_ms,
    cuda_ms,
    triton_ms,
):

    print(
        f"    PyTorch : "
        f"{pytorch_ms:.4f} ms"
    )

    print(
        f"    CUDA    : "
        f"{cuda_ms:.4f} ms   "
        f"{pytorch_ms / cuda_ms:.2f}x"
    )

    if triton_ms is not None:

        print(
            f"    Triton  : "
            f"{triton_ms:.4f} ms   "
            f"{pytorch_ms / triton_ms:.2f}x"
        )

    else:

        print(
            f"    Triton  : "
            f"NOT IMPLEMENTED"
        )


