def benchmark_rmsnorm(
    shape,
):

    B, H, N, D = shape

    x = rand_half(shape)

    weight = torch.ones(
        D,
        device=DEVICE,
        dtype=DTYPE,
    )

    dy = rand_half(shape)

    # --------------------------------------------------------
    # PYTORCH
    # --------------------------------------------------------

    torch_module = nn.RMSNorm(
        D,
        eps=EPS,
        device=DEVICE,
        dtype=torch.float32,
    )

    torch_module.weight.data.copy_(
        weight
    )

    # --------------------------------------------------------
    # CUDA
    # --------------------------------------------------------

    # CHANGE ARGUMENTS IF YOUR CUDA API DIFFERS
    def cuda_forward():

        return rmsnorm_cuda.forward(
            x,
            weight,
            EPS,
        )

    # --------------------------------------------------------
    # TRITON
    # --------------------------------------------------------

    triton_module = None

    if TritonRMSNorm is not None:

        triton_module = TritonRMSNorm(
            D,
            EPS,
        ).cuda()

        triton_module.weight.data.copy_(
            weight
        )

    # ========================================================
    # FORWARD
    # ========================================================

    torch_fwd = lambda: torch_module(x)

    cuda_fwd = lambda: cuda_forward()

    triton_fwd = (
        lambda: triton_module(x)
        if triton_module is not None
        else None
    )

    iters = choose_iters(
        x.numel()
    )

    torch_ms = bench_ms(
        torch_fwd,
        iters=iters,
    )

    cuda_ms = bench_ms(
        cuda_fwd,
        iters=iters,
    )

    triton_ms = (
        bench_ms(
            triton_fwd,
            iters=iters,
        )
        if triton_module is not None
        else None
    )

    print("\n  FORWARD")
    print_bench(
        torch_ms,
        cuda_ms,
        triton_ms,
    )

    # ========================================================
    # BACKWARD
    # ========================================================

    def torch_backward():

        xx = x.detach().float()
        xx.requires_grad_(True)

        y = torch_module(xx)

        torch.autograd.grad(
            y,
            xx,
            dy.float(),
        )

    def cuda_backward():

        rmsnorm_cuda.backward(
            dy,
            x,
            weight,
            EPS,
        )

    def triton_backward():

        xx = x.detach().clone()
        xx.requires_grad_(True)

        y = triton_module(xx)

        torch.autograd.grad(
            y,
            xx,
            dy,
        )

    torch_ms = bench_ms(
        torch_backward,
        iters=iters,
    )

    cuda_ms = bench_ms(
        cuda_backward,
        iters=iters,
    )

    triton_ms = (
        bench_ms(
            triton_backward,
            iters=iters,
        )
        if triton_module is not None
        else None
    )

    print("\n  BACKWARD")
    print_bench(
        torch_ms,
        cuda_ms,
        triton_ms,
    )


