# ROPE
# ============================================================
# ============================================================
# ROPE
# ============================================================

def benchmark_rope(shape):

    B, H, N, D = shape

    rotary_dim = D
    max_seq_len = N
    base = 10000.0
    position_offset = 0

    # --------------------------------------------------------
    # INPUTS
    # --------------------------------------------------------

    x = rand_half(shape)
    dy = rand_half(shape)

    position_ids = torch.arange(
        N,
        device=DEVICE,
        dtype=torch.long,
    ).unsqueeze(0).expand(
        B,
        -1,
    ).contiguous()

    # --------------------------------------------------------
    # TRITON ROPE MODULE
    # --------------------------------------------------------

    triton_module = TritonRoPE(
        D,
        rotary_dim=rotary_dim,
        max_seq_len=max_seq_len,
        base=base,
    ).cuda()

    # Build Triton cache.
    #
    # Triton may keep this in FP16 because x is FP16.
    # That is fine for Triton.
    #
    triton_module._build_cache(
        x.device,
        x.dtype,
    )

    cos_cache = triton_module.cos_cache
    sin_cache = triton_module.sin_cache

    # --------------------------------------------------------
    # CUDA CACHE
    # --------------------------------------------------------
    #
    # CUDA extension explicitly requires FP32 caches.
    #
    # DO NOT put these conversions inside bench_ms().
    #

    cos_cache_cuda = (
        cos_cache
        .float()
        .contiguous()
    )

    sin_cache_cuda = (
        sin_cache
        .float()
        .contiguous()
    )

    # CUDA extension expects int32 position_ids.
    position_ids_cuda = (
        position_ids
        .to(torch.int32)
        .contiguous()
    )

    # Sanity checks.
    assert cos_cache_cuda.dtype == torch.float32
    assert sin_cache_cuda.dtype == torch.float32
    assert position_ids_cuda.dtype == torch.int32

    # --------------------------------------------------------
    # CUDA FORWARD
    # --------------------------------------------------------

    def cuda_fwd():

        return rope_cuda.forward(
            x,
            position_ids_cuda,
            cos_cache_cuda,
            sin_cache_cuda,
            rotary_dim,
            position_offset,
        )

    # --------------------------------------------------------
    # TRITON FORWARD
    # --------------------------------------------------------

    def triton_fwd():

        return triton_module(
            x,
            position_ids,
            position_offset,
        )

    # --------------------------------------------------------
    # PYTORCH REFERENCE
    # --------------------------------------------------------

    def pytorch_fwd():

        xx = x.float()

        half = rotary_dim // 2

        x_rot = xx[..., :rotary_dim]
        x_tail = xx[..., rotary_dim:]

        x1 = x_rot[..., :half]
        x2 = x_rot[..., half:rotary_dim]

        pos = position_ids.long()

        cos = cos_cache_cuda[pos]
        sin = sin_cache_cuda[pos]

        cos = cos[:, None, :, :]
        sin = sin[:, None, :, :]

        y1 = (
            x1 * cos
            - x2 * sin
        )

        y2 = (
            x1 * sin
            + x2 * cos
        )

        y_rot = torch.cat(
            [y1, y2],
            dim=-1,
        )

        if rotary_dim < D:

            y = torch.cat(
                [y_rot, x_tail],
                dim=-1,
            )

        else:

            y = y_rot

        return y.to(x.dtype)

    # --------------------------------------------------------
    # ITERATIONS
    # --------------------------------------------------------

    iters = choose_iters(
        x.numel()
    )

    # ========================================================
    # FORWARD
    # ========================================================

    print("\n  FORWARD")

    # Warmup/benchmark each independently.

    pytorch_ms = bench_ms(
        pytorch_fwd,
        iters=iters,
    )

    cuda_ms = bench_ms(
        cuda_fwd,
        iters=iters,
    )

    triton_ms = bench_ms(
        triton_fwd,
        iters=iters,
    )

    print(
        f"    PyTorch : "
        f"{pytorch_ms:.4f} ms"
    )

    print(
        f"    CUDA    : "
        f"{cuda_ms:.4f} ms   "
        f"{pytorch_ms / cuda_ms:.2f}x"
    )

    print(
        f"    Triton  : "
        f"{triton_ms:.4f} ms   "
        f"{pytorch_ms / triton_ms:.2f}x"
    )

    # ========================================================
    # BACKWARD
    # ========================================================

    # --------------------------------------------------------
    # PyTorch backward
    # --------------------------------------------------------

    def pytorch_bwd():

        xx = (
            x.detach()
            .clone()
            .float()
            .requires_grad_(True)
        )

        half = rotary_dim // 2

        x_rot = xx[..., :rotary_dim]
        x_tail = xx[..., rotary_dim:]

        x1 = x_rot[..., :half]
        x2 = x_rot[..., half:rotary_dim]

        pos = position_ids.long()

        cos = cos_cache_cuda[pos]
        sin = sin_cache_cuda[pos]

        cos = cos[:, None, :, :]
        sin = sin[:, None, :, :]

        y1 = (
            x1 * cos
            - x2 * sin
        )

        y2 = (
            x1 * sin
            + x2 * cos
        )

        y_rot = torch.cat(
            [y1, y2],
            dim=-1,
        )

        if rotary_dim < D:

            y = torch.cat(
                [y_rot, x_tail],
                dim=-1,
            )

        else:

            y = y_rot

        torch.autograd.grad(
            outputs=y,
            inputs=xx,
            grad_outputs=dy.float(),
            retain_graph=False,
        )

    # --------------------------------------------------------
    # CUDA backward
    # --------------------------------------------------------
    #
    # IMPORTANT:
    #
    # CUDA signature is:
    #
    # backward(
    #     grad_out,
    #     position_ids,
    #     cos_cache,
    #     sin_cache,
    #     rotary_dim,
    #     position_offset
    # )
    #
    # There is NO x argument.
    #

    def cuda_bwd():

        return rope_cuda.backward(
            dy,
            position_ids_cuda,
            cos_cache_cuda,
            sin_cache_cuda,
            rotary_dim,
            position_offset,
        )

    # --------------------------------------------------------
    # Triton backward
    # --------------------------------------------------------

    def triton_bwd():

        xx = (
            x.detach()
            .clone()
            .requires_grad_(True)
        )

        y = triton_module(
            xx,
            position_ids,
            position_offset,
        )

        torch.autograd.grad(
            outputs=y,
            inputs=xx,
            grad_outputs=dy,
            retain_graph=False,
        )

    # ========================================================
    # BENCHMARK BACKWARD
    # ========================================================

    print("\n  BACKWARD")

    pytorch_ms = bench_ms(
        pytorch_bwd,
        iters=iters,
    )

    cuda_ms = bench_ms(
        cuda_bwd,
        iters=iters,
    )

    triton_ms = bench_ms(
        triton_bwd,
        iters=iters,
    )

    print(
        f"    PyTorch : "
        f"{pytorch_ms:.4f} ms"
    )

    print(
        f"    CUDA    : "
        f"{cuda_ms:.4f} ms   "
        f"{pytorch_ms / cuda_ms:.2f}x"
    )

    print(
        f"    Triton  : "
        f"{triton_ms:.4f} ms   "
        f"{pytorch_ms / triton_ms:.2f}x"
    )

